import type { BlockDraft, ItemDraft, Json, MediaView, SchemaNode, SectionType } from '~/utils/page-types'

/** Deep copy of JSON data (works on Vue reactive proxies, unlike structuredClone). */
export function clone<T>(value: T): T {
  return value === undefined ? value : JSON.parse(JSON.stringify(value))
}

/** RFC 9562 UUIDv7 (time-ordered): section and item ids are generated by the builder. */
export function uuidv7(now = Date.now()): string {
  const bytes = new Uint8Array(16)
  crypto.getRandomValues(bytes)
  let ts = now
  for (let i = 5; i >= 0; i--) {
    bytes[i] = ts % 256
    ts = Math.floor(ts / 256)
  }
  bytes[6] = (bytes[6]! & 0x0F) | 0x70
  bytes[8] = (bytes[8]! & 0x3F) | 0x80
  const hex = [...bytes].map(b => b.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

/** Replaces `{name}` with page variables (the opening date is formatted in the page language). */
export function interpolate(text: string | null | undefined, variables: Record<string, string | null | undefined>, locale: string): string {
  if (!text) return ''
  return text.replace(/\{(\w+)\}/g, (whole, name: string) => {
    const value = variables[name]
    if (value == null || value === '') return whole === '{opening_date}' ? '' : whole
    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
      const [y, m, d] = value.split('-').map(Number) as [number, number, number]
      return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(Date.UTC(y, m - 1, d))
    }
    return value
  }).replace(/\s{2,}/g, ' ').trim()
}

const BASE83 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz#$%*+,-.:;=?@[]^_{|}~'

/** Average colour of a blurhash (its DC component), as a CSS colour: the placeholder behind an image. */
export function blurhashColor(hash: string | null | undefined): string | undefined {
  if (!hash || hash.length < 6) return undefined
  let value = 0
  for (const c of hash.slice(2, 6)) {
    const digit = BASE83.indexOf(c)
    if (digit < 0) return undefined
    value = value * 83 + digit
  }
  return `rgb(${value >> 16} ${(value >> 8) & 255} ${value & 255})` // lint-tokens-ignore (computed, not a design colour)
}

/** `srcset` attribute from media variants. */
export function srcsetOf(media: MediaView | undefined | null): string | undefined {
  if (!media?.srcset.length) return undefined
  return media.srcset.map(v => `${v.url} ${v.width}w`).join(', ')
}

export function mediaOf(data: { media?: Record<string, MediaView> }, id: unknown): MediaView | undefined {
  return typeof id === 'string' ? data.media?.[id] : undefined
}

// ---- Schemas ----------------------------------------------------------------------------------

/** Follows a local `$ref` (`#/$defs/name`), merging the node's own keywords over the target. */
export function resolveNode(root: SchemaNode, node: SchemaNode): SchemaNode {
  const ref = node.$ref
  if (!ref?.startsWith('#/$defs/')) return node
  const target = root.$defs?.[ref.slice('#/$defs/'.length)]
  if (!target) return node
  const { $ref: _ref, ...own } = node
  return { ...resolveNode(root, target), ...own }
}

export function defaultsOf(root: SchemaNode, node: SchemaNode = root): Json {
  const n = resolveNode(root, node)
  const out: Json = {}
  for (const [key, child] of Object.entries(n.properties ?? {})) {
    const c = resolveNode(root, child)
    if (c.default !== undefined) out[key] = clone(c.default)
  }
  return out
}

/** A new section from a type's preset (as the "Add section" dialog does). */
export function blockFromPreset(type: SectionType): BlockDraft {
  const preset = type.preset ?? {}
  return {
    id: uuidv7(),
    type: type.code,
    name: null,
    anchor_id: null,
    is_visible: true,
    active_period: null,
    visible_on: 'all',
    hidden_locales: [],
    appearance: clone(preset.appearance ?? {}),
    analytics_label: null,
    settings: { ...defaultsOf(type.settings_schema), ...clone(preset.settings ?? {}) },
    content: clone(preset.content ?? {}),
    items: (preset.items ?? []).map(i => ({
      id: uuidv7(),
      settings: clone(i.settings ?? {}),
      content: clone(i.content ?? {}),
      is_visible: true,
      active_period: null,
    })),
    shared_block_id: null,
  }
}

export function newItem(type: SectionType): ItemDraft {
  return {
    id: uuidv7(),
    settings: type.item_settings_schema ? defaultsOf(type.item_settings_schema) : {},
    content: {},
    is_visible: true,
    active_period: null,
  }
}

/** Copy with fresh ids (duplicate). */
export function cloneBlock(block: BlockDraft): BlockDraft {
  const copy = clone(block)
  copy.id = uuidv7()
  copy.anchor_id = null
  copy.name = copy.name ? `${copy.name} (copie)` : null
  copy.items = copy.items.map(i => ({ ...i, id: uuidv7() }))
  delete copy.shared
  return copy
}

/** What the API accepts for a section (read-only expansion stripped). */
export function forSave(block: BlockDraft): BlockDraft {
  const { shared: _shared, ...rest } = block
  return rest as BlockDraft
}
